# RW4DM_FLOW: Flow: re-align objects from a base curve onto a target curve. The script is rw4dm_flow_script.txt; generated by rw4dm_gen.py (the closed forms are in that file). Every object kind of the case (Point, Line, Plane, Box) is
# compared with the closed-form image of the operation: points by the residual move to the origin (printed 0,0,0 within 1e-9), curve / surface control points
# through ExtractPt the same way, boxes by their bounding box after a residual move. RW4DM_FLOW_sensitivity shows that a 1e-6 error would read 1e-06.
RW4_FLOW_OUT=""
rw4_flow_run() {
  local o
  if [ -n "${DISPLAY:-}" ] && xset q >/dev/null 2>&1 || ! command -v xvfb-run >/dev/null 2>&1; then
    o="$(timeout 900 "$BIN" --smoke 60 --script "$HERE/$1" 2>&1)" || { echo "$o" | tail -40; echo "FAIL RW4DM_FLOW_run: $1 exited non-zero"; fail=1; o=""; }
  else
    o="$(timeout 900 xvfb-run -a -s "-screen 0 1600x900x24" "$BIN" --smoke 60 --script "$HERE/$1" 2>&1)" || { echo "$o" | tail -40; echo "FAIL RW4DM_FLOW_run: $1 exited non-zero"; fail=1; o=""; }
  fi
  RW4_FLOW_OUT+="$o"$'\n'
}
rw4_flow_run rw4dm_flow_script.txt
rw4_flow_block() { awk -v name="$1" '$0 ~ ("Unknown command: RW4BEGIN_" name "$") { on = 1; next } on && /Unknown command: RW4BEGIN_/ { exit } on { print }' <<<"$RW4_FLOW_OUT"; }
# rw4_flow_resid NAME NPTS BOXES DESC: the case listed exactly NPTS points, every one at residual 0,0,0, and the boxes' bounding boxes (joined by ';') read exactly BOXES
rw4_flow_resid() {
  local blk npts zeros boxes; blk="$(rw4_flow_block "$1")"
  npts="$({ grep -cE '^history: Object [0-9]+ \(point\)' <<<"$blk" || true; })"
  zeros="$({ grep -cE '^history:   0,0,0$' <<<"$blk" || true; })"
  boxes="$({ grep -E '^history: Bounding box min ' <<<"$blk" || true; } | sed -E 's/^history: Bounding box //' | paste -sd';' -)"
  if [ "$npts" = "$2" ] && [ "$zeros" = "$2" ] && [ "$boxes" = "$3" ]; then echo "ok   RW4DM_FLOW_$1: $4 ($2 points at residual 0 within 1e-9; boxes: ${3:-none})"
  else echo "FAIL RW4DM_FLOW_$1: $4 (listed $npts points, $zeros at residual 0, expected $2 and $2; boxes '$boxes', expected '$3')"; fail=1; { grep -E '^history:   |^history: Bounding box|^history: ! ' <<<"$blk" || true; } | head -16 | sed 's/^/     residual: /'; fi
}
rw4_flow_resid rigid 9 "" "Flow from the base line (0,0,0)-(10,0,0) to the equally long line (20,0,0)-(20,10,0): a point and a plane keep their distances along and from the curve (a 90 degree turn: (x,y,z) -> (20 - y, x, z))"
rw4_flow_resid copy 14 "" "Flow Copy=Yes leaves the originals and adds the flowed copies"
rw4_flow_resid longer 9 "" "Flow onto a longer target (length 20): without Stretch the distance along the curve is kept (the object is not stretched)"
rw4_flow_resid stretch 9 "" "Flow Stretch=Yes onto the length-20 target stretches the along-curve coordinate by 2 (the offsets from the curve are kept)"
rw4_flow_resid tilted 9 "" "Flow onto the target (20,0,0)-(20,6,8) rising in 3-D: the frame (tangent, up made perpendicular to it, their cross product) carries the offsets"
# negative control: the same harness must SEE a 1e-6 error (a point 1e-6 off its expected image reads 1e-06, not 0)
rw4_flow_sens() {
  local blk; blk="$(rw4_flow_block sensitivity)"
  if grep -qE '^history:   (0,0,)?[-0-9.e]*1e-06' <<<"$blk" && ! grep -qE '^history:   0,0,0$' <<<"$blk"; then echo "ok   RW4DM_FLOW_sensitivity: the residual harness reports a 1e-6 error as 1e-06 (negative control)"
  else echo "FAIL RW4DM_FLOW_sensitivity: a 1e-6 error was not visible"; fail=1; { grep -E '^history:   ' <<<"$blk" || true; } | head -4 | sed 's/^/     residual: /'; fi
}
rw4_flow_sens
